                                        type="range" 
                                        min="0" 
                                        max={backingTrack.buffer?.duration || 10} 
                                        step="0.01" 
                                        value={backingTrack.trimEnd || (backingTrack.buffer?.duration || 10)}
                                        onChange={(e) => {
                                            const v = parseFloat(e.target.value);
                                            if (v > backingTrack.trimStart) setBackingTrack({ ...backingTrack, trimEnd: v });
                                        }}
                                        className="w-full accent-red-500"
                                     />
                                 </div>

                                 <div className="space-y-1">
                                     <div className="flex justify-between text-[10px] text-slate-400 uppercase font-bold">
                                         <span>Volume</span>
                                         <span>{(backingTrack.volume * 100).toFixed(0)}%</span>
                                     </div>
                                     <input 
                                        type="range" 
                                        min="0" 
                                        max="1" 
                                        step="0.01" 
                                        value={backingTrack.volume}
                                        onChange={(e) => setBackingTrack({ ...backingTrack, volume: parseFloat(e.target.value) })}
                                        className="w-full accent-white"
                                     />
                                 </div>
                             </div>
                        </div>
                    )}
                    <input type="file" accept="audio/*" className="hidden" ref={backingInputRef} onChange={handleBackingTrackUpload} />
                </div>
             </div>
        )}

        {activeTab === 'SAMPLER' && (
            <div className="h-full flex flex-col gap-4 animate-in zoom-in-95 duration-300">
                <div className="flex justify-between items-end px-2">
                    <div>
                        <h2 className="text-sm font-bold text-synth-pop flex items-center gap-2"><Music2 size={16}/> WEIRD VOICE CREATOR</h2>
