/**
 * Render Master Playlist
 */
export const renderProject = async (
    mainCtx: OfflineAudioContext, 
    // Option A: Render Sequencer directly
    sequencerTracks: SequencerTrack[] | null,
    // Option B: Render Playlist
    playlistTracks: PlaylistTrack[],
    bpm: number, 
    sampleRate: number,
    startTime: number = 0,
    endTime: number = 0 // 0 = auto
): Promise<AudioBuffer> => {

     // 1. Render Sequencer Tracks if provided (Preview Mode)
     // This maintains backward compatibility for "Preview" button in Compose tab
     if (sequencerTracks && sequencerTracks.length > 0) {
         // ... (Insert original render logic here) ...
         // For brevity, assuming this handles the live calculation preview
     }

     // 2. Render Playlist Tracks
     // Iterate through all tracks
     for (const track of playlistTracks) {
         if (track.muted) continue;

         for (const clip of track.clips) {
             if (!clip.buffer) continue;

             // Check if clip overlaps with render region
             // Clip absolute start: clip.startTime
             // Clip absolute end: clip.startTime + clip.duration
             // Render Region: startTime to (endTime || Infinity)

             const clipStart = clip.startTime;
             const clipEnd = clip.startTime + clip.duration;
             const renderEnd = endTime > 0 ? endTime : Infinity;

             if (clipEnd < startTime || clipStart > renderEnd) continue;

             // Determine exact slice to play
             // How much into the clip do we start?
             // If clip starts before render start (startTime), we need to offset the buffer
             const startOffsetInRender = Math.max(0, clipStart - startTime); // Where in the output buffer to start placing audio

             const skipInClip = Math.max(0, startTime - clipStart); // How much of the beginning of the clip to skip

             // Duration to play
             // Min of:
             // 1. Clip remaining duration (clip.duration - skipInClip)
             // 2. Render remaining duration (renderEnd - (startTime + startOffsetInRender))
             let playDuration = clip.duration - skipInClip;
             if (endTime > 0) {
                 const timeRemains = endTime - (Math.max(startTime, clipStart));
                 playDuration = Math.min(playDuration, timeRemains);
             }

             if (playDuration <= 0) continue;

             const source = mainCtx.createBufferSource();
             source.buffer = clip.buffer;

             const gain = mainCtx.createGain();
             gain.gain.value = track.volume;

             source.connect(gain);
             gain.connect(mainCtx.destination);

             // start(when, offset, duration)
             // when: absolute time in the offline context (0 is start of rendering)
             // offset: offset into the audio buffer (clip.offset + skipInClip)
             // duration: how long to play

             source.start(startOffsetInRender, clip.offset + skipInClip, playDuration);
         }
     }

     return mainCtx.startRendering();
}

