                                value={activeTrack.vocalParams.customData?.sampler?.rootNote || 60}
                                onChange={(e) => updateSamplerConfig({ rootNote: parseInt(e.target.value) })}
                            />
                        </div>

                        <div className="flex items-center gap-2">
