  };

  const handleSaveCustomPreset = () => {
      try {
          const parsed = JSON.parse(editorContent);
          const name = prompt(calcMode === 'PLUGIN' ? "Name for this Plugin Engine:" : "Name for this Algo:", selectedEditorPreset || "My_Custom_Algo");
          if (!name) return;

          if (calcMode === 'PLUGIN') {
