                    >
                        {activeTrack.vocalParams.preset === VocalPreset.SAMPLER ? 'ACTIVE' : 'ACTIVATE SAMPLER'}
                    </button>
                </div>

                <div className="flex-1 bg-synth-panel rounded-xl border border-synth-grid flex flex-col overflow-hidden relative">
