export const getNoteFromMidi = (midi: number) => {
    const notes = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
    return notes[midi % 12];
};

export const isNoteInScale = (midi: number, root: string, scale: ScaleType): boolean => {
    const rootBase = NOTE_FREQUENCIES[root];
    if (!rootBase) return true;

    const notes = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
    const rootIndex = notes.indexOf(root);

    const noteIndex = midi % 12;
    const interval = (noteIndex - rootIndex + 12) % 12;

    return SCALE_INTERVALS[scale].includes(interval);
};

export const getFrequency = (note: string, octave: number): number => {
  const base = NOTE_FREQUENCIES[note] || 16.35;
  return base * Math.pow(2, octave);
};

export const midiToFreq = (midi: number): number => {
  return 440 * Math.pow(2, (midi - 69) / 12);
};

// --- AUDIO UTILS ---

export const decodeAudioData = async (ctx: AudioContext | OfflineAudioContext, base64: string): Promise<AudioBuffer> => {
    const binaryString = window.atob(base64.split(',')[1]);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return await ctx.decodeAudioData(bytes.buffer);
};

export const detectSlices = (buffer: AudioBuffer, sensitivity: number): {start: number, end: number}[] => {
    const data = buffer.getChannelData(0);
    const step = Math.floor(buffer.sampleRate / 100); 
    const slices = [];
    const threshold = 0.01 + ((1 - sensitivity) * 0.1);

    let isSilent = true;
    let startSample = 0;

    for(let i=0; i<data.length; i+=step) {
        let sum = 0;
        for(let j=0; j<step && i+j<data.length; j++) {
            sum += data[i+j] * data[i+j];
        }
        const rms = Math.sqrt(sum / step);

        if (isSilent && rms > threshold) {
            isSilent = false;
            startSample = i;
        } else if (!isSilent && rms < threshold) {
            isSilent = true;
            if (i - startSample > step * 5) { 
                slices.push({
                    start: startSample / data.length,
                    end: i / data.length
                });
            }
        }
    }
    if (!isSilent) {
        slices.push({
            start: startSample / data.length,
            end: 1.0
        });
    }
    if (slices.length === 0) return [{start: 0, end: 1}];
    return slices;
};

// --- ENCODING UTILS ---

export const bufferToMp3 = (buffer: AudioBuffer, bitrate: number): Blob => {
    if (typeof lamejs === 'undefined') {
        throw new Error("LameJS not found. Cannot encode MP3.");
    }

    const channels = buffer.numberOfChannels;
    const sampleRate = buffer.sampleRate;
    const mp3enc = new lamejs.Mp3Encoder(channels, sampleRate, bitrate);
    const left = buffer.getChannelData(0);
    const right = channels > 1 ? buffer.getChannelData(1) : left;

    const sampleBlockSize = 1152;
    const mp3Data = [];

    const l16 = new Int16Array(left.length);
    const r16 = new Int16Array(right.length);
    for(let i=0; i<left.length; i++) {
        l16[i] = Math.max(-1, Math.min(1, left[i])) * 32767;
        r16[i] = Math.max(-1, Math.min(1, right[i])) * 32767;
    }

    for (let i = 0; i < l16.length; i += sampleBlockSize) {
        const leftChunk = l16.subarray(i, i + sampleBlockSize);
        const rightChunk = r16.subarray(i, i + sampleBlockSize);
        let mp3buf;
        if (channels === 1) {
            mp3buf = mp3enc.encodeBuffer(leftChunk);
        } else {
            mp3buf = mp3enc.encodeBuffer(leftChunk, rightChunk);
        }
        if (mp3buf.length > 0) mp3Data.push(mp3buf);
    }

    const endBuf = mp3enc.flush();
    if (endBuf.length > 0) mp3Data.push(endBuf);

    return new Blob(mp3Data, { type: 'audio/mp3' });
};

export const bufferToWav = (buffer: AudioBuffer, bitDepth: 8 | 16 | 32 = 16): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = bitDepth === 32 ? 3 : 1; 
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numOfChan * bytesPerSample;
  const length = buffer.length * blockAlign + 44;
  const bufferArr = new ArrayBuffer(length);
  const view = new DataView(bufferArr);
  const channels = [];
  let i;
  let offset = 0;
  let pos = 0;

  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); 
  setUint32(0x45564157); // "WAVE"
  setUint32(0x20746d66); // "fmt "
  setUint32(16); 
  setUint16(format); 
  setUint16(numOfChan);
  setUint32(sampleRate);
  setUint32(sampleRate * blockAlign); 
  setUint16(blockAlign); 
  setUint16(bitDepth); 
  setUint32(0x61746164); // "data"
  setUint32(length - pos - 4); 

  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  let sample;
  while (pos < length) {
    if (offset >= buffer.length) break;
    for (i = 0; i < numOfChan; i++) {
       sample = Math.max(-1, Math.min(1, channels[i][offset]));
       if (bitDepth === 8) {
           sample = ((sample * 0.5 + 0.5) * 255);
           view.setUint8(pos, sample);
           pos += 1;
       } 
       else if (bitDepth === 16) {
           sample = (sample < 0 ? sample * 32768 : sample * 32767) | 0;
           view.setInt16(pos, sample, true);
           pos += 2;
       } 
       else if (bitDepth === 32) {
           view.setFloat32(pos, sample, true);
           pos += 4;
       }
    }
    offset++;
  }

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }

  return new Blob([bufferArr], { type: 'audio/wav' });
};

export const applyReverb = async (ctx: OfflineAudioContext, inputBuffer: AudioBuffer, mix: number, decayTime: number): Promise<AudioBuffer> => {
  if (mix <= 0) return inputBuffer;

  const sampleRate = ctx.sampleRate;
  const length = inputBuffer.length;

  const irLength = sampleRate * decayTime;
  const irBuffer = ctx.createBuffer(1, irLength, sampleRate);
  const irData = irBuffer.getChannelData(0);

  for (let i = 0; i < irLength; i++) {
    irData[i] = (Math.random() * 2 - 1) * Math.pow(1 - (i / irLength), 4);
  }

  const convCtx = new OfflineAudioContext(1, length, sampleRate);
  const source = convCtx.createBufferSource();
  source.buffer = inputBuffer;

  const convolver = convCtx.createConvolver();
  convolver.buffer = irBuffer;
  convolver.normalize = true;

  const dryGain = convCtx.createGain();
  const wetGain = convCtx.createGain();

  dryGain.gain.value = 1 - (mix * 0.5);
  wetGain.gain.value = mix;

  source.connect(dryGain);
  dryGain.connect(convCtx.destination);

  source.connect(convolver);
  convolver.connect(wetGain);
  wetGain.connect(convCtx.destination);

  source.start();
  return await convCtx.startRendering();
};

/**
 * DSP Synthesis Engine (Formants, Oscillators, Envelope)
 */
export const renderVocals = async (ctx: OfflineAudioContext, params: VocalParams, duration: number, baseFreq: number, startFreq?: number): Promise<AudioBuffer> => {
    // 1. Prepare Config
    const sampleRate = ctx.sampleRate;
    const buffer = ctx.createBuffer(1, Math.ceil(sampleRate * duration), sampleRate);
    const data = buffer.getChannelData(0);

    // Get Preset Data
    let preset = params.customData;
    if (!preset && params.preset) {
        preset = VOCAL_PRESETS_DATA[params.preset];
    }
    if (!preset) preset = VOCAL_PRESETS_DATA[VocalPreset.MALE_BR];

    // Determine Vowel / Formants logic
    let vChar = (params.vowel || 'A').toLowerCase();

    // Attempt to extract vowel from text (lyric) if present
    if (params.text && params.text.length > 0) {
        const t = params.text.toLowerCase();
        if (t.includes('a') || t.includes('ã')) vChar = 'a';
        else if (t.includes('e') || t.includes('é') || t.includes('ê')) vChar = 'e';
        else if (t.includes('i') || t.includes('í')) vChar = 'i';
        else if (t.includes('o') || t.includes('ó') || t.includes('ô')) vChar = 'o';
        else if (t.includes('u') || t.includes('ú')) vChar = 'u';
    }

    const phoneme = PHONEME_LIB[vChar] || PHONEME_LIB['a'];
    const formantScale = (preset.formantScale || 1.0) * (params.formantShift || 1.0);

    // Filter Setup (Parallel Resonators)
    const formants = phoneme.f.map(f => f * formantScale);
    const bandwidths = phoneme.bw || [100, 100, 100, 100];

    // Filter coefficients for each formant
    // 2-pole resonant filter approximation
    const filters = formants.map((freq, i) => {
        const bw = bandwidths[i] || 100;
        const r = Math.exp(-Math.PI * bw / sampleRate);
        const theta = 2 * Math.PI * freq / sampleRate;
        return {
            c1: 2 * r * Math.cos(theta),
            c2: -r * r,
            gain: (1 - r) * Math.sqrt(1 - 2*r*Math.cos(2*theta) + r*r), // Gain normalization
            y1: 0, y2: 0
        };
    });

    // Oscillator State
    let phase = 0;
    const glideTime = 0.1; // seconds for portamento transition
    let currentFreq = startFreq || baseFreq;
    const targetFreq = baseFreq;

    // Params
    const breathAmount = (preset.breath || 0) + (params.breathiness || 0);
    const jitter = (preset.jitter || 0) + (params.jitter || 0);
    const vibRate = (preset.vibrato?.rate || 5);
    const vibDepth = (preset.vibrato?.depth || 0);

    // --- SAMPLE LOOP ---
    for (let i = 0; i < data.length; i++) {
        const t = i / sampleRate;

        // 1. Pitch Logic
        // Glide
        if (startFreq && t < glideTime) {
            const p = t / glideTime;
            // Ease-out curve
            currentFreq = startFreq + (targetFreq - startFreq) * (p * (2 - p)); 
        } else {
            currentFreq = targetFreq;
        }

        // Vibrato + Jitter
        const vib = Math.sin(t * vibRate * 2 * Math.PI) * vibDepth * currentFreq;
        const jit = (Math.random() - 0.5) * jitter * currentFreq;

        const f = Math.max(20, currentFreq + vib + jit); // Floor freq to avoid crash
        const inc = f / sampleRate;
        phase += inc;
        if (phase >= 1.0) phase -= 1.0;

        // 2. Source Generation (Glottal Pulse)
        let source = 0;

        switch(preset.type) {
            case 'sawtooth':
                // Band-limited-ish raw saw
                source = 1.0 - 2.0 * phase;
                // Cubic polynomial softening to simulate glottal closure (less buzz)
                source = source - 0.5 * (source * source * source); 
                break;
            case 'square':
                source = phase < 0.5 ? 1 : -1;
                break;
            case 'pulse':
                source = phase < 0.15 ? 1 : -1; // Narrow pulse
                break;
            case 'triangle':
                source = 2 * Math.abs(2 * (phase - Math.floor(phase + 0.5))) - 1;
                break;
            case 'sine':
                source = Math.sin(phase * 2 * Math.PI);
                break;
            case 'custom':
                // Hybrid pulse/noise
                source = (1.0 - 2.0 * phase) * 0.5 + (Math.random() * 2 - 1) * 0.5;
                break;
            default:
                source = 1.0 - 2.0 * phase;
        }

        // Add Noise (Breath)
        const noise = (Math.random() * 2 - 1) * breathAmount;

        // Input to filters (Source + Noise)
        // Oscillator reduced as breath increases
        const input = source * (1 - breathAmount * 0.5) + noise;

        // 3. Formant Filtering
        let out = 0;
        // Skip filters if "sine" or simple type without formantScale change
        // Actually, always apply filters for "voice" feel unless disabled
        if (params.preset !== VocalPreset.SYNTH_BELL && params.preset !== VocalPreset.E_PIANO) {
            for (let k = 0; k < filters.length; k++) {
                const filt = filters[k];
                // Difference equation: y[n] = gain*x[n] + c1*y[n-1] + c2*y[n-2]
                const y = filt.gain * input + filt.c1 * filt.y1 + filt.c2 * filt.y2;
                filt.y2 = filt.y1;
                filt.y1 = y;
                out += y;
            }
        } else {
            out = input; // Bypass filters for synth sounds
        }

        // 4. Post-Process Effects

        // Distortion/Saturation
        if (preset.distortion) {
            out *= (1 + preset.distortion * 4);
            out = Math.tanh(out);
        }

        // Bitcrush / Steps
        if (preset.steps) {
            const stepSize = 0.2;
            out = Math.round(out / stepSize) * stepSize;
        }

        // Hard Clip
        if (preset.clip) {
            if (out > preset.clip) out = preset.clip;
            if (out < -preset.clip) out = -preset.clip;
        }

        data[i] = out * 0.5; // Master gain for note
    }

    // Apply Amplitude Envelope (ADSR) to prevent clicks
    // Simple Attack/Release for now
    const attack = 0.01 * sampleRate;
    const release = 0.05 * sampleRate;
    const len = data.length;

    for(let i=0; i<attack && i<len; i++) {
        data[i] *= (i / attack);
    }
    for(let i=0; i<release && len-1-i >= 0; i++) {
        data[len-1-i] *= (i / release);
    }

    return buffer;
};

/**
 * Render Master Playlist
 */
export const renderProject = async (
    mainCtx: OfflineAudioContext, 
    sequencerTracks: SequencerTrack[] | null,
    playlistTracks: PlaylistTrack[],
    bpm: number, 
    sampleRate: number,
    startTime: number = 0,
    endTime: number = 0 
): Promise<AudioBuffer> => {

     // 1. Render Sequencer Tracks (Preview/Pattern Mode)
     if (sequencerTracks && sequencerTracks.length > 0) {
         for (const track of sequencerTracks) {
             if (track.muted) continue;
             for (const note of track.notes) {
                 const start = note.startTime * (60 / bpm);
                 const dur = note.duration * (60 / bpm);
                 const freq = midiToFreq(note.midi);

                 // Create effective params combining track params + note specifics (lyrics)
                 const effectiveParams: VocalParams = {
                     ...track.vocalParams,
                     text: note.lyric || track.vocalParams.text
                 };

                 // Render note with DSP engine
                 const noteBuffer = await renderVocals(mainCtx, effectiveParams, dur, freq);

                 // Mix into mainCtx
                 const source = mainCtx.createBufferSource();
                 source.buffer = noteBuffer;
                 const gain = mainCtx.createGain();
                 gain.gain.value = track.volume;
                 source.connect(gain);
                 gain.connect(mainCtx.destination);
                 source.start(start);
             }
         }
     }

     // 2. Render Playlist Tracks (DAW Mode)
     for (const track of playlistTracks) {
         if (track.muted) continue;
         for (const clip of track.clips) {
             if (!clip.buffer) continue;

             const clipStart = clip.startTime;
             const clipEnd = clip.startTime + clip.duration;
             const renderEnd = endTime > 0 ? endTime : Infinity;

             if (clipEnd < startTime || clipStart > renderEnd) continue;

             const startOffsetInRender = Math.max(0, clipStart - startTime);
             const skipInClip = Math.max(0, startTime - clipStart);

             let playDuration = clip.duration - skipInClip;
             if (endTime > 0) {
                 const timeRemains = endTime - (Math.max(startTime, clipStart));
                 playDuration = Math.min(playDuration, timeRemains);
             }

             if (playDuration <= 0) continue;

             const source = mainCtx.createBufferSource();
             source.buffer = clip.buffer;
             const gain = mainCtx.createGain();
             gain.gain.value = track.volume;
             source.connect(gain);
             gain.connect(mainCtx.destination);

             source.start(startOffsetInRender, clip.offset + skipInClip, playDuration);
         }
     }

     return mainCtx.startRendering();
}

import { 
  VocalPreset, VocalMode, VocalParams, SequencerNote, SequencerTrack, AudioPresetDefinition, PluginDefinition, SamplerConfig, VocalLanguage, ScaleType, PlaylistTrack
} from '../types';

declare const lamejs: any;

// Constants
export const NOTE_FREQUENCIES: Record<string, number> = {
  'C': 16.35, 'C#': 17.32, 'D': 18.35, 'D#': 19.45, 'E': 20.60, 'F': 21.83,
