// Consonants: DSP configurations for onset articulation
interface ConsonantDef {
    type: 'fricative' | 'plosive' | 'nasal' | 'liquid';
    dur: number; // Duration in seconds
    noise: number; // Noise mix (0-1)
    oscMix: number; // Oscillator mix (0-1)
    filterHighPass?: number; // Cutoff for noise
    formantMod?: number[]; // Temporary formant targets
}

