// --- PHONEME DATA ---

// Vowels: Formant Frequencies (Hz) and Bandwidths
// Extended for PT-BR Nasals and variations
const VOWEL_LIB: Record<string, { f: number[], bw: number[], g: number, nasal?: boolean }> = {
