                        {activeTrack.vocalParams.preset === VocalPreset.SAMPLER && (
                             <p className="text-[9px] text-pink-400 mt-1 italic font-bold">SAMPLER MODE ACTIVE! Go to the SAMPLER tab to configure.</p>
