              <Piano size={20} />
              <span className="text-[9px] font-bold">COMPOSE</span>
          </button>
          <button onClick={() => setActiveTab('PLAYLIST')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors min-w-[64px] ${activeTab === 'PLAYLIST' ? 'text-emerald-400' : 'text-slate-500 hover:text-slate-300'}`}>
              <ListMusic size={20} />
              <span className="text-[9px] font-bold">PLAYLIST</span>
          </button>
           <button onClick={() => setActiveTab('RACK')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors min-w-[64px] ${activeTab === 'RACK' ? 'text-synth-accent' : 'text-slate-500 hover:text-slate-300'}`}>
              <Layers size={20} />
              <span className="text-[9px] font-bold">RACK</span>
          </button>
           <button onClick={() => setActiveTab('VOICE')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors min-w-[64px] ${activeTab === 'VOICE' ? 'text-synth-accent' : 'text-slate-500 hover:text-slate-300'}`}>
              <Sliders size={20} />
              <span className="text-[9px] font-bold">VOICE</span>
          </button>
           <button onClick={() => setActiveTab('SAMPLER')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors min-w-[64px] ${activeTab === 'SAMPLER' ? 'text-synth-pop animate-pulse-slow' : 'text-slate-500 hover:text-slate-300'}`}>
              <Music2 size={20} />
              <span className="text-[9px] font-bold">SAMPLER</span>
          </button>
