                                                    className={`w-full text-left text-[10px] px-2 py-2 rounded truncate ${selectedEditorPreset === name ? 'bg-synth-accent text-black font-bold' : 'text-slate-300 hover:bg-slate-700'}`}
                                                >
                                                    {name}
